(function() {
  const termExplanations = {
    'y': '结果变量 (如每小时解决数 RPH)',
    'delta': '时间固定效应 (控制季节性因素如报税季)',
    'alpha': '代理固定效应 (控制不随时间变化的个人能力)',
    'beta': 'AI 处理效应系数 (核心因果参数)',
    'gamma': '其他控制变量系数 (如任期)',
    'epsilon': '误差项'
  };

  const tableData = [
    { group: '未处理组 (Never Treated)', aht: '43', rph: '1.7' },
    { group: '处理前 (Treated, Pre)', aht: '43', rph: '2.0' },
    { group: '处理后 (Treated, Post)', aht: '35', rph: '2.5' }
  ];

  const equationEl = document.getElementById('regression-equation');
  const explanationEl = document.getElementById('term-explanation');
  const tableBody = document.getElementById('productivity-table-body');

  // 公式交互
  equationEl.addEventListener('click', function(e) {
    if (e.target.classList.contains('term')) {
      document.querySelectorAll('.term').forEach(t => t.classList.remove('active'));
      e.target.classList.add('active');
      const termKey = e.target.getAttribute('data-term');
      explanationEl.innerHTML = `<strong>${termKey}</strong>: ${termExplanations[termKey] || '未知项'}`;
    }
  });

  // 表格渲染
  tableBody.innerHTML = tableData.map(row => 
    `<tr>
      <td>${row.group}</td>
      <td>${row.aht}</td>
      <td>${row.rph}</td>
    </tr>`
  ).join('');

  // 来源按钮事件 (由内核处理)
  document.querySelectorAll('.source-btn').forEach(btn => {
    btn.addEventListener('click', function() {
      // 内核将拦截 data-source 属性
    });
  });

  // 初始化显示默认解释
  explanationEl.innerHTML = '<p>点击公式中的项以查看其含义及控制变量作用。</p>';
})();
